import{_ as a,o as n,c as t,a5 as s}from"./chunks/framework.pJebtgMf.js";const m=JSON.parse('{"title":"AI 动态 · 2026-08-29","description":"","frontmatter":{"title":"AI 动态 · 2026-08-29","date":"2026-08-29T00:00:00.000Z","outline":[2,3]},"headers":[],"relativePath":"news/2026-08/ai-news-2026-08-29.md","filePath":"news/2026-08/ai-news-2026-08-29.md","lastUpdated":null}'),r={name:"news/2026-08/ai-news-2026-08-29.md"};function o(i,e,c,p,l,d){return n(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="ai-动态-·-2026-08-29" tabindex="-1">AI 动态 · 2026-08-29 <a class="header-anchor" href="#ai-动态-·-2026-08-29" aria-label="Permalink to &quot;AI 动态 · 2026-08-29&quot;">​</a></h1><blockquote><p>截至 2026-08-29。业界 · 产品 · 模型 · 开源 · 开发者工具 · 前端。</p></blockquote><div class="news-section" data-section="业界"><h2 id="业界" tabindex="-1">业界 <a class="header-anchor" href="#业界" aria-label="Permalink to &quot;业界&quot;">​</a></h2><h3 id="nvidia的ai优势正超越gpu本身" tabindex="-1">Nvidia的AI优势正超越GPU本身 <a class="header-anchor" href="#nvidia的ai优势正超越gpu本身" aria-label="Permalink to &quot;Nvidia的AI优势正超越GPU本身&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-08-29">2026-08-29</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/9a8f3bbd90f2.jpg" alt="配图"></p><p>Nvidia在AI领域的领先地位正从GPU硬件扩展到更智能的数据中心系统。新一代系统通过更智能的流量控制而非单纯增加处理器周期来提升效率，标志着Nvidia在AI基础设施领域的战略重心正在转移。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/08/29/nvidias-ai-advantage-is-moving-beyond-the-gpu/" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="neocloud-lambda获10亿美元债务融资采购ai芯片" tabindex="-1">Neocloud Lambda获10亿美元债务融资采购AI芯片 <a class="header-anchor" href="#neocloud-lambda获10亿美元债务融资采购ai芯片" aria-label="Permalink to &quot;Neocloud Lambda获10亿美元债务融资采购AI芯片&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-08-29">2026-08-29</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/d1b626573316.png" alt="配图"></p><p>AI云公司Lambda通过摩根大通安排获得10亿美元私人短期债务，用于购买Nvidia AI芯片并租赁给微软。这是该公司一系列贷款中的最新一笔，凸显了AI热潮下高昂的资本支出成本。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/08/28/neocloud-lambda-secures-1b-in-debt-to-buy-more-chips/" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="联邦法官裁定特朗普政府将anthropic列入黑名单违法" tabindex="-1">联邦法官裁定特朗普政府将Anthropic列入黑名单违法 <a class="header-anchor" href="#联邦法官裁定特朗普政府将anthropic列入黑名单违法" aria-label="Permalink to &quot;联邦法官裁定特朗普政府将Anthropic列入黑名单违法&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Ars Technica AI</span><time datetime="2026-08-29">2026-08-29</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/898f7f58376b.jpg" alt="配图"></p><p>美国联邦法官裁定，特朗普政府因Anthropic拒绝支持致命自主武器和监控技术而将其列为国家安全供应链风险的行为属于非法报复。法院已撤销相关政府指令，这对AI公司的政策立场保护具有里程碑意义。</p><p class="news-entry-source"><a href="https://arstechnica.com/tech-policy/2026/08/trump-blacklisting-of-woke-anthropic-deemed-illegal-by-federal-judge/" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="产品"><h2 id="产品" tabindex="-1">产品 <a class="header-anchor" href="#产品" aria-label="Permalink to &quot;产品&quot;">​</a></h2><h3 id="openai决定终止向被spacex收购的cursor提供模型" tabindex="-1">OpenAI决定终止向被SpaceX收购的Cursor提供模型 <a class="header-anchor" href="#openai决定终止向被spacex收购的cursor提供模型" aria-label="Permalink to &quot;OpenAI决定终止向被SpaceX收购的Cursor提供模型&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">OpenAI Blog</span><time datetime="2026-08-28">2026-08-28</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/e3b5d8c1beff.png" alt="配图"></p><p>OpenAI宣布将终止向Cursor提供其模型的合同，提议的关闭日期为2026年11月12日。OpenAI表示，基于与马斯克公司违反合同的经历，无法确信SpaceX会遵守其服务条款。此举将影响Cursor用户的模型选择。</p><p class="news-entry-source"><a href="https://openai.com/index/our-decision-on-cursor-following-its-acquisition-by-spacex" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="openai正在开发-持久化-ai代理" tabindex="-1">OpenAI正在开发“持久化”AI代理 <a class="header-anchor" href="#openai正在开发-持久化-ai代理" aria-label="Permalink to &quot;OpenAI正在开发“持久化”AI代理&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Wired AI</span><time datetime="2026-08-28">2026-08-28</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/3e1ca1bad882.jpg" alt="配图"></p><p>据WIRED审查的代码显示，OpenAI正在为其旗舰AI代理Codex开发“持久模式”功能，使Codex能够主动持续工作，直到被“休眠”。该功能已在Codex命令行版本中开始添加代码，未来可能扩展到其他代理产品。</p><p class="news-entry-source"><a href="https://www.wired.com/story/openai-is-developing-a-persistent-ai-agent/" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="wps多维表格-灵感应用-亮相-自然语言即可搭建业务应用" tabindex="-1">WPS多维表格“灵感应用”亮相：自然语言即可搭建业务应用 <a class="header-anchor" href="#wps多维表格-灵感应用-亮相-自然语言即可搭建业务应用" aria-label="Permalink to &quot;WPS多维表格“灵感应用”亮相：自然语言即可搭建业务应用&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">36氪</span><time datetime="2026-08-29">2026-08-29</time></p><p>WPS多维表格推出全新功能“灵感应用”，用户用自然语言描述业务需求，AI即可生成可直接使用、持续迭代的个性化业务应用。该功能基于WPS多维表格已有的数据、权限与协作能力，让不懂代码的业务人员也能搭建应用。</p><p class="news-entry-source"><a href="https://36kr.com/newsflashes/3960320361790599?f=rss" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="模型"><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><h3 id="千问办公发布qwen3-8-flash-token消耗减少75" tabindex="-1">千问办公发布Qwen3.8-Flash：Token消耗减少75% <a class="header-anchor" href="#千问办公发布qwen3-8-flash-token消耗减少75" aria-label="Permalink to &quot;千问办公发布Qwen3.8-Flash：Token消耗减少75%&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-08-28">2026-08-28</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/62cc9e1ad403.jpg" alt="配图"></p><p>阿里千问大模型团队发布多模态MoE模型Qwen3.8-Flash，主模型125B参数，每个Token仅激活6B参数，输入每百万Tokens仅0.8元。同步上线千问办公标准模式，单任务生成速度提升约100%，Token消耗平均减少75%，覆盖约95%日常任务。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/70zHFKxwRRGIjBO8EUtC?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="开源"><h2 id="开源" tabindex="-1">开源 <a class="header-anchor" href="#开源" aria-label="Permalink to &quot;开源&quot;">​</a></h2><p>（本日无新条目）</p></div><div class="news-section" data-section="开发者工具"><h2 id="开发者工具" tabindex="-1">开发者工具 <a class="header-anchor" href="#开发者工具" aria-label="Permalink to &quot;开发者工具&quot;">​</a></h2><h3 id="duckdb-v2-0预览-从嵌入式数据库迈向分布式架构" tabindex="-1">DuckDB v2.0预览：从嵌入式数据库迈向分布式架构 <a class="header-anchor" href="#duckdb-v2-0预览-从嵌入式数据库迈向分布式架构" aria-label="Permalink to &quot;DuckDB v2.0预览：从嵌入式数据库迈向分布式架构&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-08-28">2026-08-28</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/8a7c6af98b30.jpg" alt="配图"></p><p>DuckDB Labs发布v2.0预览版，代号“Cyanoptera”，引入原生客户端/服务器模式，支持通过quack协议和CONNECT SQL语句进行网络连接。同时推出版本化C API和稳定ABI保证，扩展可一次构建多版本运行，正式版计划秋季发布。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/9YLW3ZxLvrqxOVzSh9Y1?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="阿里qoder推出桌面端-coding不再是程序员专属" tabindex="-1">阿里Qoder推出桌面端：Coding不再是程序员专属 <a class="header-anchor" href="#阿里qoder推出桌面端-coding不再是程序员专属" aria-label="Permalink to &quot;阿里Qoder推出桌面端：Coding不再是程序员专属&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">量子位</span><time datetime="2026-08-29">2026-08-29</time></p><p>阿里Qoder发布全新桌面端，将Agentic Coding能力从IDE中解放出来。用户可通过桌面宠物进行实时语音交互，用自然语言描述需求即可生成完整应用。Qoder已服务全球600万用户和10万家企业客户，支持通过Computer Use和Browser Use自主验证代码。</p><p class="news-entry-source"><a href="https://www.qbitai.com/2026/08/480940.html" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="keenable获2600万美元融资-为ai-agent重建搜索引擎" tabindex="-1">Keenable获2600万美元融资：为AI Agent重建搜索引擎 <a class="header-anchor" href="#keenable获2600万美元融资-为ai-agent重建搜索引擎" aria-label="Permalink to &quot;Keenable获2600万美元融资：为AI Agent重建搜索引擎&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-08-29">2026-08-29</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/7e371d0e8cb5.png" alt="配图"></p><p>前Yandex搜索负责人创立的Keenable走出隐身状态，完成2600万美元种子轮融资。公司自建Web Index覆盖超1000亿文档，p95延迟低于250ms，千次请求最低1美元，旨在成为AI Agent时代的“下一个Google”，API已接入多家AI Labs生产环境。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/KbbHdAQFxQM7AJIYMLqR?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="前端"><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><p>（本日无新条目）</p></div>',8)])])}const u=a(r,[["render",o]]);export{m as __pageData,u as default};
